1	var taskStates = {
2	    new: '',
3	    inprogress: 'inprogress',
4	    completed: 'Completed',
5	    waiting: 'Waiting',
6	    error: 'Error',
7	    looperror: 'LoopError',
8	    skipped: 'WillNotBeExecuted',
9	    blocked: 'Blocked'
10	};
11	
12	function mapToArray(m) {
13	    var arr = [];
14	    for (var k in m) {
15	        arr.push(m[k]);
16	    }
17	    return arr;
18	}
19	
20	function getSubPlaybookTasks(tasks) {
21	  var readyTasks = [];
22	  arinks = [];
23	  (tasks || []).forEach(function (task) {
24	    if (task.type === 'playbook' && task.subPlaybook) {
25	      readyTasks = readyTasks.concat(getSubPlaybookTasks(mapToArray(task.subPlaybook.tasks)));
26	    }
27	    readyTasks.push(task);
28	  });
29	
30	  return readyTasks;
31	}
32	
33	function getAllPlaybookTasks(tasks) {
34	  if (!tasks || tasks.length === 0) {
35	    return [];
36	  }
37	  return getSubPlaybookTasks(tasks);
38	}
39	
40	function getStates(states) {
41	    var input_states = states.split(",");
42	    if (input_states.indexOf('error') > -1) {
43	        input_states = input_states.concat('loopError')
44	    }
45	    var readyStates = {};
46	    input_states.forEach(function(state) {
47	        var systemState = taskStates[state.trim().toLowerCase()];
48	        if (systemState !== null && systemState !== undefined) {
49	         readyStates[systemState] = true;
50	        }
51	    });
52	
53	    if (Object.keys(readyStates).length === 0) {
54	        Object.keys(taskStates).forEach(function(k) {
55	            readyStates[taskStates[k]] = true;
56	        });
57	    }
58	
59	    return readyStates;
60	}
61	
62	var states = getStates(args.states || '');
63	var inc_id = args.inc_id;
64	var res = executeCommand('core-api-get', {'uri': '/investigation/' + inc_id + '/workplan'});
65	if (isError(res[0])) {
66	    return res;
67	}
68	
69	var workplan = dq(res[0],'Contents.response.invPlaybook');
70	
71	if (!workplan || !workplan.tasks || workplan.tasks.length === 0) {
72	    return 'Workplan for incident ' + inc_id + ', has no tasks.';
73	}
74	
75	var tasks = mapToArray(workplan.tasks);
76	var allTasks = getAllPlaybookTasks(tasks);
77	
78	var res = [];
79	for (var id in allTasks) {
80	    var task = allTasks[id];
81	    if (states[task.state] !== null && states[task.state] !== undefined) {
82	        res.push({
83	            id: task.id,
84	            name: task.task.name,
85	            type: task.type,
86	            owner: task.assignee,
87	            state: task.state,
88	            scriptId: task.task.scriptId,
89	            startDate: task.startDate,
90	            dueDate: task.dueDate,
91	            completedDate: task.completedDate,
92	            parentPlaybookID: task.parentPlaybookID,
93	            completedBy: task.completedBy
94	        });
95	    }
96	}
97	
98	entry = {
99	    Type: entryTypes.note,
100	    Contents: res,
101	    ContentsFormat: formats.json,
102	    ReadableContentsFormat: formats.markdown,
103	    HumanReadable: tableToMarkdown('Tasks with states ' + args.states + ' (Incident #' + inc_id + ')', res, ['id', 'name', 'state', 'owner', 'scriptId']),
104	    EntryContext: {
105	        Tasks: res
106	    }
107	};
108	
109	return entry;
